        faq: [
          { q: 'La meva empresa hi està obligada si té menys de 50 treballadors?', a: 'En general, no. L\'obligació comença als 50 treballadors. Amb independència de la mida, també hi estan obligades les entitats dels sectors que cita l\'article 10.1 b), com els serveis financers o la prevenció del blanqueig de capitals, i, segons l’article 10.1 c), els partits, els sindicats i les organitzacions empresarials que rebin o gestionin fons públics. Una empresa no obligada pot implantar el canal de manera voluntària.' },
          { q: 'Com sap qui denuncia que la seva denúncia és anònima?', a: 'El canal li mostra, abans de començar, quines dades es registren i quines no. En mode anònim el formulari no demana nom, correu ni telèfon, i el seguiment es fa amb un codi, sense compte.' },
          { q: 'Què passa si qui denuncia perd el seu codi?', a: 'El codi és l\'única manera de consultar una denúncia anònima i no es pot recuperar. La denúncia continua al panell i es gestiona igual, però aquesta persona n\'hauria de presentar una de nova per tornar a comunicar-s\'hi.' },
          { q: 'Qui pot veure les denúncies dins de l\'empresa?', a: 'Només les persones que l\'administrador convidi com a gestors. A cadascuna se li assignen les categories que pot veure i què hi pot fer: veure, editar, respondre o eliminar. Cada acció queda al registre d\'auditoria.' },
          { q: 'Com s\'afegeix el canal a la nostra web?', a: 'Amb un enllaç. Des del panell es copia l\'adreça del canal, un botó per a la web o un codi QR per a cartells. No cal instal·lar res.' },
          { q: 'Quant es triga a posar-lo en marxa?', a: 'El canal queda actiu en crear el compte i confirmar el correu. Després només cal compartir l\'enllaç i convidar els gestors.' },
          { q: 'Què hem de fer nosaltres, a més de contractar el canal?', a: 'Tres passos que només pot fer la seva organització. Són a «El que correspon a la seva empresa», dins de Compliment.' },
          { q: 'Com es paga?', a: 'Amb una quota anual segons la mida de l\'empresa. Durant la prova no es demana cap dada de pagament.' },
        ],
