        faqMore: '¿Tiene otra pregunta?',
        faqWrite: 'Escríbanos a',
        faq: [
          { q: '¿Mi empresa está obligada si tiene menos de 50 trabajadores?', a: 'En general, no. La obligación empieza en 50 trabajadores. Con independencia del tamaño, también están obligadas las entidades de los sectores que cita el artículo 10.1 b), como los servicios financieros o la prevención del blanqueo de capitales, y, según el artículo 10.1 c), los partidos, los sindicatos y las organizaciones empresariales que reciban o gestionen fondos públicos. Una empresa no obligada puede implantar el canal de forma voluntaria.' },
          { q: '¿Cómo sabe quien denuncia que su denuncia es anónima?', a: 'El canal le muestra, antes de empezar, qué datos se registran y cuáles no. En modo anónimo el formulario no pide nombre, correo ni teléfono, y el seguimiento se hace con un código, sin cuenta.' },
          { q: '¿Qué ocurre si quien denuncia pierde su código?', a: 'El código es la única forma de consultar una denuncia anónima y no se puede recuperar. La denuncia sigue en el panel y se gestiona igual, pero esa persona tendría que presentar una nueva para volver a comunicarse.' },
          { q: '¿Quién puede ver las denuncias dentro de la empresa?', a: 'Solo las personas que el administrador invite como gestores. A cada una se le asignan las categorías que puede ver y lo que puede hacer en ellas: ver, editar, responder o eliminar. Cada acción queda en el registro de auditoría.' },
          { q: '¿Cómo se añade el canal a nuestra web?', a: 'Con un enlace. Desde el panel se copia la dirección del canal, un botón para la web o un código QR para carteles. No hay que instalar nada.' },
          { q: '¿Cuánto se tarda en ponerlo en marcha?', a: 'El canal queda activo al crear la cuenta y confirmar el correo. Después solo hay que compartir el enlace e invitar a los gestores.' },
          { q: '¿Qué tenemos que hacer nosotros, además de contratar el canal?', a: 'Tres pasos que solo puede dar su organización. Están en «Lo que corresponde a su empresa», dentro de Cumplimiento.' },
          { q: '¿Cómo se paga?', a: 'Con una cuota anual según el tamaño de la empresa. Durante la prueba no se pide ningún dato de pago.' },
        ],
